import org.springframework.beans.factory.support.DefaultListableBeanFactory;
import org.springframework.beans.factory.xml.XmlBeanDefinitionReader;
import org.springframework.context.ApplicationContext;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.core.io.ClassPathResource;

public class SpringContainerDemo {
    public static void main(String[] args) {
        // Low-level BeanFactory usage (Lazy initialization)
        DefaultListableBeanFactory factory = new DefaultListableBeanFactory();
        XmlBeanDefinitionReader reader = new XmlBeanDefinitionReader(factory);
        reader.loadBeanDefinitions(new ClassPathResource("beans.xml"));
        System.out.println("BeanFactory initialized. Beans not yet created.");

        // High-level ApplicationContext usage (Eager initialization)
        ApplicationContext context = new AnnotationConfigApplicationContext(AppConfig.class);
        System.out.println("ApplicationContext initialized. Singletons are instantiated.");
    }
}
